#pragma once

#include "mtmd-impl.h"
#include "mtmd-vision-bf16-diagnostics.h"
#include <string_view>

// This review inventory is intentionally explicit, never generated by a build.
// Scope the mandatory diagnostic to this function, not other upstream switches.
#if defined(__clang__) || defined(__GNUC__)
#pragma GCC diagnostic push
#pragma GCC diagnostic error "-Wswitch-enum"
#else
#error "BF16 projector review coverage needs exhaustive enum diagnostics"
#endif
static inline constexpr int32_t lcb_mtmd_review_projector(projector_type type) {
    switch (type) {
    case PROJECTOR_TYPE_MLP:
    case PROJECTOR_TYPE_MLP_NORM:
    case PROJECTOR_TYPE_QWEN2VL:
    case PROJECTOR_TYPE_QWEN25VL:
    case PROJECTOR_TYPE_QWEN3VL:
    case PROJECTOR_TYPE_GEMMA3:
    case PROJECTOR_TYPE_GEMMA4V:
    case PROJECTOR_TYPE_GEMMA4UV:
    case PROJECTOR_TYPE_LFM2:
    case PROJECTOR_TYPE_LFM3VL:
    case PROJECTOR_TYPE_MUSE_GLIMMER:
        return MTMD_VISION_BF16_CANDIDATE_REVIEWED;
    // These are audio encoders, speaker encoders or audio generators. They do
    // not inherit the vision storage policy, even within a multimodal file.
    case PROJECTOR_TYPE_GEMMA3NA:
    case PROJECTOR_TYPE_GEMMA4A:
    case PROJECTOR_TYPE_GEMMA4UA:
    case PROJECTOR_TYPE_ULTRAVOX:
    case PROJECTOR_TYPE_QWEN2A:
    case PROJECTOR_TYPE_QWEN3A:
    case PROJECTOR_TYPE_GLMA:
    case PROJECTOR_TYPE_HIGGS_AUDIO:
    case PROJECTOR_TYPE_VIBEVOICE_ASR:
    case PROJECTOR_TYPE_VOXTRAL:
    case PROJECTOR_TYPE_VOXTRAL_RT:
    case PROJECTOR_TYPE_MERALION:
    case PROJECTOR_TYPE_MUSIC_FLAMINGO:
    case PROJECTOR_TYPE_DOTS3NOTE_A:
    case PROJECTOR_TYPE_LFM2A:
    case PROJECTOR_TYPE_D1OMNI_A:
    case PROJECTOR_TYPE_LFM3A:
    case PROJECTOR_TYPE_PARAKEET:
    case PROJECTOR_TYPE_GRANITE_SPEECH:
    case PROJECTOR_TYPE_NEMOTRON_TRANSCRIBE:
    case PROJECTOR_TYPE_MIMO_AUDIO:
    case PROJECTOR_TYPE_QWEN3TTS_SPKENC:
    case PROJECTOR_TYPE_QWEN3TTS_GEN:
    case PROJECTOR_TYPE_POCKETTTS_SPKENC:
    case PROJECTOR_TYPE_POCKETTTS_GEN:
    case PROJECTOR_TYPE_SOPRANO:
    case PROJECTOR_TYPE_KOKORO:
    case PROJECTOR_TYPE_TINY_VOCA:
    case PROJECTOR_TYPE_LFM3A_GEN:
    case PROJECTOR_TYPE_DRAMA3_GEN:
    case PROJECTOR_TYPE_ZONOS3_GEN:
    case PROJECTOR_TYPE_ZONOS3_SPKENC:
    case PROJECTOR_TYPE_YUE2_GEN:
    case PROJECTOR_TYPE_VOXCPM2_GEN:
    case PROJECTOR_TYPE_VOXCPM2_SPKENC:
    case PROJECTOR_TYPE_MINIMAX_MUSIC3_GEN:
    case PROJECTOR_TYPE_FISH_S2_GEN:
    case PROJECTOR_TYPE_FISH_S2_SPKENC:
    case PROJECTOR_TYPE_MUSE_SPARK_AUDIO:
    case PROJECTOR_TYPE_CHATTERBOX:
    case PROJECTOR_TYPE_CHATTERBOX_SPKENC:
        return MTMD_VISION_BF16_CANDIDATE_NOT_APPLICABLE;
    // No retention proof has been established for these vision families. This
    // is pending review, not a claim that keeping their BF16 bytes is impossible.
    case PROJECTOR_TYPE_LDP:
    case PROJECTOR_TYPE_LDPV2:
    case PROJECTOR_TYPE_MINICPMV:
    case PROJECTOR_TYPE_GLM_EDGE:
    case PROJECTOR_TYPE_LING3VL:
    case PROJECTOR_TYPE_STEP3VL:
    case PROJECTOR_TYPE_GEMMA3NV:
    case PROJECTOR_TYPE_PHI4:
    case PROJECTOR_TYPE_IDEFICS3:
    case PROJECTOR_TYPE_PIXTRAL:
    case PROJECTOR_TYPE_INTERNVL:
    case PROJECTOR_TYPE_LLAMA4:
    case PROJECTOR_TYPE_D1OMNI_V:
    case PROJECTOR_TYPE_KIMIVL:
    case PROJECTOR_TYPE_PADDLEOCR:
    case PROJECTOR_TYPE_LIGHTONOCR:
    case PROJECTOR_TYPE_COGVLM:
    case PROJECTOR_TYPE_JANUS_PRO:
    case PROJECTOR_TYPE_DOTS_OCR:
    case PROJECTOR_TYPE_DOTS3NOTE_V:
    case PROJECTOR_TYPE_DEEPSEEKOCR:
    case PROJECTOR_TYPE_DEEPSEEKOCR2:
    case PROJECTOR_TYPE_DEEPSEEK4V:
    case PROJECTOR_TYPE_DEEPSEEK41V:
    case PROJECTOR_TYPE_GLM4V:
    case PROJECTOR_TYPE_GLM5V:
    case PROJECTOR_TYPE_YOUTUVL:
    case PROJECTOR_TYPE_YASA2:
    case PROJECTOR_TYPE_KIMIK25:
    case PROJECTOR_TYPE_KIMIK31:
    case PROJECTOR_TYPE_NEMOTRON_V2_VL:
    case PROJECTOR_TYPE_NEMOTRON_OMNI:
    case PROJECTOR_TYPE_HUNYUANVL:
    case PROJECTOR_TYPE_EXAONE4_5:
    case PROJECTOR_TYPE_MINICPMV4_6:
    case PROJECTOR_TYPE_MINICPMV4_7:
    case PROJECTOR_TYPE_MINICPM_OCR_1_0:
    case PROJECTOR_TYPE_MIMOVL:
    case PROJECTOR_TYPE_MAGEVL:
    case PROJECTOR_TYPE_MINIMAX_M3:
    case PROJECTOR_TYPE_GRANITE4_VISION:
    case PROJECTOR_TYPE_SENSENOVA_U1:
    case PROJECTOR_TYPE_COHERE2V:
    case PROJECTOR_TYPE_INKLING2V:
        return MTMD_VISION_BF16_CANDIDATE_UNREVIEWED;
    case PROJECTOR_TYPE_QWEN25O:
        // Ambiguous without modality; metadata normalization below selects the
        // vision family only when has_vision is explicitly true.
    case PROJECTOR_TYPE_UNKNOWN:
    default:
        return MTMD_VISION_BF16_CANDIDATE_UNKNOWN;
    }
}
#if defined(__clang__) || defined(__GNUC__)
#pragma GCC diagnostic pop
#endif

static inline int32_t lcb_mtmd_classify_metadata(int32_t has_vision, const char * common, const char * vision) {
    if (has_vision == 0)
        return MTMD_VISION_BF16_CANDIDATE_NOT_APPLICABLE;
    if (has_vision != 1)
        return MTMD_VISION_BF16_CANDIDATE_UNKNOWN;
    const char * name = common && common[0] ? common : vision;
    if (!name || !name[0])
        return MTMD_VISION_BF16_CANDIDATE_UNKNOWN;
    size_t length = 0;
    while (length < 128 && name[length])
        ++length;
    if (length == 128)
        return MTMD_VISION_BF16_CANDIDATE_UNKNOWN;
    // Do not construct a std::string (and potentially allocate) at this C ABI.
    // The upstream name table is the single source for spelling and aliases.
    auto type = PROJECTOR_TYPE_UNKNOWN;
    for (const auto & entry : PROJECTOR_TYPE_NAMES) {
        if (std::string_view(entry.second) == std::string_view(name, length)) {
            type = entry.first;
            break;
        }
    }
    if (type == PROJECTOR_TYPE_QWEN25O)
        type = PROJECTOR_TYPE_QWEN25VL;
    return lcb_mtmd_review_projector(type);
}
